<?php
namespace App\Http\Controllers;
use App\Models\{Product,StockBalance,StockMovement,StockAdjustment};use App\Services\InventoryService;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
class InventoryController extends Controller{
 public function index(Request $r){$products=Product::with(['baseUnit','stock','businessUnit','category'])->when($r->q,fn($q)=>$q->where('name','like','%'.$r->q.'%'))->when($r->low,fn($q)=>$q->whereHas('stock',fn($s)=>$s->whereColumn('quantity','<=','products.alert_quantity')))->orderBy('name')->paginate(30)->withQueryString();return view('inventory.index',compact('products'));}
 public function movements(Request $r){$movements=StockMovement::with('product')->latest()->paginate(40);return view('inventory.movements',compact('movements'));}
 public function adjust(Request $r,InventoryService $inventory){$d=$r->validate(['product_id'=>'required|exists:products,id','actual_quantity'=>'required|numeric|min:0','reason'=>'required|string|max:190']);DB::transaction(function()use($d,$inventory){$p=Product::with('baseUnit')->findOrFail($d['product_id']);$b=StockBalance::firstOrCreate(['product_id'=>$p->id,'product_variant_id'=>null],['quantity'=>0,'avg_cost'=>$p->purchase_price]);$before=(float)$b->quantity;$actual=(float)$d['actual_quantity'];$diff=$actual-$before;StockAdjustment::create(['adjustment_no'=>'ADJ-'.now()->format('ymd').'-'.Str::upper(Str::random(4)),'product_id'=>$p->id,'system_quantity'=>$before,'actual_quantity'=>$actual,'difference'=>$diff,'reason'=>$d['reason'],'adjusted_at'=>now(),'user_id'=>auth()->id()]);if($diff!=0){$b->quantity=$actual;$b->save();StockMovement::create(['product_id'=>$p->id,'reference_type'=>'adjustment','reference_id'=>null,'direction'=>'adjustment','quantity'=>abs($diff),'unit_cost'=>$b->avg_cost,'unit_name'=>$p->baseUnit->short_name,'note'=>$d['reason'].' ('.$diff.')','user_id'=>auth()->id()]);}});return back()->with('success','Stock adjusted successfully.');}
}
